
import React from 'react';
import { Button } from "@heroui/react";
import VerticalDotsSvg from './VerticalDotsSvg';

function VerticalDotsIcon({ onClick }) {
    return (
        <div className="flex gap-4 items-center text-white">
            <Button size='sm' onClick={onClick} isIconOnly aria-label="Edit">
                <VerticalDotsSvg />
            </Button>

        </div>
    )
}

export default VerticalDotsIcon