import React, { useEffect, useState } from 'react'
import useApi from '../../hooks/useApi'
import { useNavigate, useParams } from 'react-router-dom';
import { getLoggedInUser } from '../../helpers/authUtils';
import { deleteDraftOrder, retrieveDraftCustomerOrders, saveDraftOrder } from '../../helpers/retailerHelpers';
import { Input, Link, Tab, Tabs } from "@heroui/react";
import ordersApi from '../../api/orders/ordersApi';
import { Loading, YesNoModal } from '../../components';
import ClosedOrdersTable from '../retailers/orders/ClosedOrdersTable';
import DraftOrdersTable from '../retailers/orders/DraftOrdersTable';
import DraftOrdersFormModal from '../retailers/orders/DraftOrdersFormModal';
import { useStateContext } from '../../contexts/ContextProvider';
import ShoppingOrderFormModal from './ShoppingOrderFormModal';

const closedOrderColumns = [

    { name: "Customer Name", uid: "customer_name" },
    { name: "Customer Phone", uid: "customer_phone" },
    { name: "Order Total", uid: "order_net_price_total" },
    { name: "Order Origin", uid: "order_origin" },

    { name: "Actions", uid: "actions" },
];

const draftOrderColumns = [

    { name: "Customer Name", uid: "customer_name" },
    { name: "Customer Phone", uid: "customer_phone" },
    { name: "Order Total", uid: "order_net_price_total" },


    { name: "Actions", uid: "actions" },
];
function OrdersList() {

    const [openDraftOrderFormModal, setopenDraftOrderFormModal] = useState(false)
    const [openClosedtFormModal, setopenClosedFormModal] = useState(false)
    const navigate = useNavigate()
    const [closedOrder, setClosedOrder] = useState()
    const [closedOrders, setClosedOrders] = useState([])
    const [closedOrdersdata, setClosedOrdersData] = useState([])
    const [draftOrdersdata, setDraftOrdersData] = useState([])
    const [updated, setUpdated] = useState(false)
    const [modalTitle, setmodalTitle] = useState("")
    const closedOrdersActionsApi = useApi(ordersApi.ordersAction)
    const [selected, setSelected] = React.useState("login");
    const [draftCustomerOrders, setdraftCustomerOrders] = useState([]);
    const [draftOrderToDelete, setdraftOrderToDelete] = useState()

    const [showYesNoModal, setshowYesNoModal] = useState(false)

    const [user, setUser] = useState()
    const {
        loggedInUser,
        currentColor

    } = useStateContext();

    useEffect(() => {
        const orders = retrieveDraftCustomerOrders().filter(x => x.customer && x.customer === loggedInUser.id)
        setdraftCustomerOrders(orders);
    }, []);



    useEffect(() => {
        setUser(getLoggedInUser())

    }, [])

    const getEntityCustomerOrders = async (user) => {
        setClosedOrders([])
        await closedOrdersActionsApi.request({
            "action": "RetrieveOwnOrders"
        })
    }


    useEffect(() => {
        getEntityCustomerOrders()
    }, [])

    useEffect(() => {
        getEntityCustomerOrders()
        const orders = retrieveDraftCustomerOrders().filter(x => x.customer && x.customer === loggedInUser.id)
        setdraftCustomerOrders(orders);
    }, [openDraftOrderFormModal])


    const handleEditAction = (item) => {

        setopenDraftOrderFormModal(true)

        // setUpdated(false)

        setClosedOrder(item)
        setmodalTitle(`${item.title}`)

    }

    const handleAddDraftOrderAction = () => {


        setopenDraftOrderFormModal(true)
        setopenClosedFormModal(true)

        setUpdated(false)

        setmodalTitle("Add new draft order")
        setClosedOrder(null)
    }
    const handleViewClosedAction = () => {


        setopenDraftOrderFormModal(true)
        setopenClosedFormModal(true)

        setUpdated(false)

        setmodalTitle("Add new department")
        setClosedOrder(null)
    }
    const handleDetailsAction = (item) => {


        navigate(`/retailers/departments/details/${item.id}`, {
            state: {
                'item': item
            }
        })
    }
    const handleDeleteAction = (item) => {

        navigate(`/retailers/departments/delete/${item.id}`)
    }


    useEffect(() => {

        if (closedOrdersActionsApi.data && closedOrdersActionsApi.data.length) {

            setClosedOrders(closedOrdersActionsApi.data)
        }

        console.log('closedOrdersActionsApi.data', closedOrdersActionsApi.data)
    }, [closedOrdersActionsApi.data])

    useEffect(() => {

    }, [openDraftOrderFormModal, openClosedtFormModal])

    //Filtering data
    useEffect(() => {
        setClosedOrdersData(closedOrders)
    }, [closedOrders])

    useEffect(() => {
        setDraftOrdersData(draftCustomerOrders)
    }, [draftCustomerOrders]);


    const handleFilterClosedOrders = (e) => {


        const search_param = e

        if (closedOrders && closedOrders.length > 0 && search_param && search_param !== '') {
            setClosedOrdersData(closedOrders.filter((x) => x.customer_name.toLowerCase().includes(search_param)));
        } else {
            setClosedOrdersData(closedOrdersActionsApi.data);
        }

    };

    const handleFilterDraftOrders = (e) => {


        const search_param = e

        if (draftCustomerOrders && draftCustomerOrders.length > 0 && search_param && search_param !== '') {
            setDraftOrdersData(draftCustomerOrders.filter((x) => x.customer_name.toLowerCase().includes(search_param)));
        } else {
            setDraftOrdersData(draftCustomerOrders);
        }

    };

    const handleShowDeleteDialog = (e) => {
        console.log('Delete', e)
        setshowYesNoModal(true)
        setdraftOrderToDelete(e)
    }

    const handleDeleteDraftOrder = async () => {
        if (draftOrderToDelete) {
            const res = await deleteDraftOrder(draftOrderToDelete.draft_id)
            if (res) {
                setdraftOrderToDelete(null)
                console.log('resss', res)
                setshowYesNoModal(false)
                const orders = retrieveDraftCustomerOrders().filter(x => x.customer && x.customer === user.id)
                setdraftCustomerOrders(orders);
            }

        }
    }

    const handleEditDraftOrderAction = (e) => {

        navigate(`/shopfront/${e.entity}/order/${e.draft_id}`, {
            state: {
                'order': e
            }
        })
    }
    return closedOrdersActionsApi.loading ? <Loading loading={closedOrdersActionsApi.loading} /> : (
        <div>
            <YesNoModal showModal={showYesNoModal} header="Delete Draft Order" content="Action is irreversible!" setShowModal={setshowYesNoModal} yesAction={handleDeleteDraftOrder} />
            <Tabs
                fullWidth
                size="md"
                aria-label="Tabs form"
                selectedKey={selected}
                onSelectionChange={setSelected}
            >
                <Tab key="draft-orders" title="Draft Customer Orders">


                    {openDraftOrderFormModal && <ShoppingOrderFormModal openEditModal={openDraftOrderFormModal} setopenEditModal={setopenDraftOrderFormModal} item={closedOrder} updated={updated} setUpdated={setUpdated} modalTitle={modalTitle} />}
                    <DraftOrdersTable data={draftOrdersdata} columns={draftOrderColumns}
                        editAction={handleEditDraftOrderAction} detailsAction={handleDetailsAction} deleteAction={handleShowDeleteDialog} addAction={handleAddDraftOrderAction} handleFilter={handleFilterDraftOrders} />
                </Tab>
                <Tab key="complete-orders" title="Complete Customer Orders">

                    <ClosedOrdersTable data={closedOrdersdata} columns={closedOrderColumns}
                        editAction={handleEditAction} detailsAction={handleDetailsAction} deleteAction={handleDeleteAction} handleFilter={handleFilterClosedOrders} />
                </Tab>
            </Tabs>

        </div>
    )
}

export default OrdersList